namespace TaskFlow.Api.Models;
public class Category { public int Id { get; set; } public string OwnerId { get; set; } = ""; public string Name { get; set; } = ""; public string Color { get; set; } = "#4759D6"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Workspace { public int Id { get; set; } public string Name { get; set; } = ""; public string JoinCode { get; set; } = ""; public string LeaderUserId { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class WorkspaceMember { public int Id { get; set; } public int WorkspaceId { get; set; } public string UserId { get; set; } = ""; public string Role { get; set; } = "Member"; public DateTime JoinedAt { get; set; } = DateTime.UtcNow; public DateTime? LeftAt { get; set; } }
public enum TaskStatus { Todo, InProgress, Done, Archived }
public enum TaskPriority { Low, Normal, High, Urgent }
public class TaskItem { public int Id { get; set; } public string OwnerId { get; set; } = ""; public string? CreatedByUserId { get; set; } public int? WorkspaceId { get; set; } public string Title { get; set; } = ""; public string Description { get; set; } = ""; public int? CategoryId { get; set; } public DateTime? DueAt { get; set; } public int? ReminderIntervalMinutes { get; set; } public DateTime? ReminderUntil { get; set; } public bool IsLocked { get; set; } public TaskPriority Priority { get; set; } = TaskPriority.Normal; public TaskStatus Status { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; public byte[] RowVersion { get; set; } = []; }
public class TaskComment { public int Id { get; set; } public int TaskId { get; set; } public string UserId { get; set; } = ""; public string Content { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class TaskReminder { public int Id { get; set; } public int TaskId { get; set; } public string UserId { get; set; } = ""; public DateTime RemindAt { get; set; } public bool IsSent { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class TaskNotice { public int Id { get; set; } public string UserId { get; set; } = ""; public int TaskId { get; set; } public string Message { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime? ReadAt { get; set; } }
public class TaskAttachment { public int Id { get; set; } public int TaskId { get; set; } public string FileName { get; set; } = ""; public string StorageName { get; set; } = ""; public string ContentType { get; set; } = "application/octet-stream"; public long Size { get; set; } public string UploadedByUserId { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
